    """ Get minimum number from list `numbers` (inclusive) that's larger than `lower_bound` """
    if not numbers:
        return None
    lowest = numbers[0]
    for num in numbers:
        if num < lowest:
            lowest = num
    if lowest > lower_bound:
        return lowest
    return None


