        if len(s) == 0:
            prefixes.append('')
        elif i == 0:
            prefixes.append(s[0])
        elif i > 0 and s[0] == list_of_strings[i - 1][0]:
            prefix = s[0]
            for j in range(1, len(s)):
                if s[j] != list_of_strings[i - 1][j]:
                    prefix = s[:j]
                    break
            prefixes.append(prefix)
        else:
            prefixes.append('')
    return prefixes

