def caesar_cipher(message: str, shift: int = 3) -> str:
    """ A Caesar cipher is a simple encryption technique that uses a letter to shift it by a
    given number of places in a cycle.
    >>> caesar_cipher('Hello')
    'Khoor'
    """
    result = ''
    for char in message:
        if char.isalpha():
            ascii_val = ord(char)
            if ascii_val >= 65 and ascii_val <= 90:
                new_ascii_val = ascii_val + shift
                if new_ascii_val > 90:
                    new_ascii_val = new_ascii_val - 26
                result += chr(new_ascii_val)
            elif ascii_val >= 97 and ascii_val <= 122:
                new_ascii_val = ascii_val + shift
                if new_ascii_val > 122:
                    new_ascii_val = new_ascii_val - 26
                result += chr(new_ascii_val)
        else:
            result += char
    return result


