def subset_sum(target_sum: int, nums: list):
    """This function returns True if there is a subset of the list nums
    such that the sum of its elements is equal to target_sum. Otherwise, it returns False.
    >>> subset_sum(0, [])
    True
    >>> subset_sum(1, [1])
    False
    >>> subset_sum(2, [1, 2, 3])
    True
    >>> subset_sum(4, [1, 2, 3])
    False
    """
    if target_sum == 0:
        return True
    if target_sum < 0:
        return False
    return subset_sum(target_sum - nums[0], nums[1:]) or subset_sum(target_sum, nums[1:])

