def encode_run_length(s: str):
    """
    returns encoded string by making groups of n chars.
    """
    groups = list(s)
    prev_char = groups[0]
    count = 1
    for i in range(1, len(groups)):
        current_char = groups[i]
        if current_char != prev_char:
            if count == 1:
                groups[count] = current_char
            else:
                groups.append(current_char)
            count = 1
        else:
            count += 1
        prev_char = current_char
    if count > 1:
        groups.append(prev_char)
        if count == 2:
            groups[1] = prev_char
        else:
            groups[2] = prev_char
    return "".join(groups)


