    """
    Given an array, return the number of triples where the first is less than
    the second is less than the third.  We allow only positive integers
    """

    # we need to go through every pair of numbers, and check if the third number is
    # greater than the two others.
    count = 0
    for i in range(0, len(array)):
        for j in range(i + 1, len(array)):
            for k in range(j + 1, len(array)):
                if array[i] + array[j] + array[k] > 0:
                    count += 1

    return count


