def my_zip(*arrays):
    """
    Given an arbitrary number of arrays, zip these arrays together and return a
    generator which will also zip together the last arrays
    """

    l = list()
    l.append(len(arrays))
    for i in range(0, l[0]):
        l.append([])
    for arrays in zip(*arrays):
        for i, j in zip(arrays, l):
            l[i].append(j[i % len(arrays)])

    return l


