def mod(n, m):
    """
    multiplies n by m and returns the last digit of the product. i.e
    (374 * 12) = 4560, so mod(4560, 10) returns 0, since 4560 % 10 = 0.
    """
    return n * m % 10


def factorial(n):
    """
    multiplies all numbers from 1 to n. i.e 5 factorial is 5 * 4 * 3 * 2 * 1,
    so factorail(5) is 5 * 4 * 3 * 2 * 1
    """
    return sum(range(1, n + 1))


def combinations(n, r):
    """
    to compute c(n, r), n choose r. i.e. C(n,r) = n! / (r! * (n-r)!)"""
    return factorial(n) // (factorial(r) * factorial(n - r))


