def pascal_number(n):
    """
    to compute the nth pascal number, which is the sum of all possible
    numbers that can be formed with a given number of elements in a row.
    For example, with 3, there is just 1 number, and the pascal number is 1.
    For 4, the pascals triangle will be [1, 1, 1, 1, 1],
    but the 5th element in the triangle is 5, since 1 + 1 + 1 + 1 + 1 = 5.
    """
    return (n * factorial(n)) // (factorial(n - 1) * factorial(n - 2))


