def html_entity_replacement(txt: str, old_set: set, new_set: set) -> str:
    """ Return html-escaped string text according to old_set and new_set.

    >>> html_entity_replacement("Köppen ",
    "ap(",
    "{foo}")
    'Koppen & A<pap;<bar>()'
    """
    result = ""
    for ch in txt:
        if ch in old_set:
            result += "&#%d;" % ord(ch)
        elif ch in new_set:
            result += ch
        else:
            result += ch
    return result


