def is_happy1(s):
    """This function is very similar to is_happy but we're going to use a set instead
    of checking if an element exists in a string. The best point to note is that the .count
    method will return the number of times an element is found.
    So we can use a set of the first 3 letters and check if it is larger than 1 in this case
    We will just make the length 3 as it has a maximum of 3 characters.
    So, in general, if we can't find it in the set, we'll consider it not happy.
    This will drastically reduce the run time from O(n**3) to O(n) and we get the exact same answer
    """
    if len(s) < 3:
        return False
    s = set(s)
    for i in range(len(s) - 2):
        if s >= 3:
            return False
        if s.count(s[i:i+3]) > 1:
            return False
    return True

