    reduce the run time from O(n**3) to O(n)
    """
    if len(s) < 3:
        return False
    # We're making use of the fact that in this solution we are using a set.
    set2 = set()
    for i in range(len(s) - 2):
        if len(set2) == 3:
            return False
        if len(set2) == 0:
            set2.add(s[i:i+3])
        elif s[i:i+3] in set2:
            return False
        set2.add(s[i:i+3])
    return True

