def flip(n):
    """
    Given a positive integer n, return the number of integers up to n
    that do not start or end with the same digit.
    """
    def unique_digit(s):
        """Returns true if all digits in s are unique."""
        s = list(s)
        s.sort()
        for i in range(len(s)-1):
            if s[i] == s[i+1]:
                return False
        return True

    def flip_or_flip_up(s):
        """Returns the number of integers up to n that start or end with
        a unique digit."""
        s = str(s)
        n = len(s)
        if n == 1:
            return 0
        if n == 2:
            if unique_digit(s):
                return 0
            return 1
        elif n == 3:
            if unique_digit(s):
                return 0
            return 2
        else:
            return (flip_or_flip_up(s[:-1]) + flip_or_flip_up(s[1:]))%mod

    return sum((unique_digit(i) + flip_or_flip_up(i))%mod for i in range(1, n+1))


