    """
    Given a sorted list of numbers and a number, find and return the index
    of that number in the list.
    """
    l = 0
    h = len(list1)-1
    while l <= h:
        mid = l + (h-l)//2
        if list1[mid] == target:
            return mid
        elif list1[mid] < target:
            l = mid+1
        else:
            h = mid-1
    return -1

