    Write a function that takes a sorted list of numbers and a number,
    and returns the index of that number in the list.
    """
    def search(l, h):
        if h < l:
            return -1
        mid = l + (h-l)//2
        if list1[mid] == target:
            return mid
        elif list1[mid] < target:
            return search(mid+1, h)
        else:
            return search(l, mid-1)

    return search(0, len(list1)-1)

