def pascal(x, y):
    """This function returns the x,y coordinate of the point that is closest
    to the origin. The value of x and y should be as small as possible. For
    example: if x = 3 and y = 2, then the function should return (3, 2)<|fim_suffix|>    Example:
    pascal(2, 2) = (1, 1)
    pascal(2, 5) = (5, 0)
    """
    if x < 0 or y < 0:
        return (None, None)
    elif x == 0 and y == 0:
        return (0, 0)
    elif x == 0:
        return (1, 0)
    elif y == 0:
        return (0, 1)
    else:
        sum = x + y
        num_row = sum // 2
        prev_row = num_row
        curr_row = 0
        for i in range(0, num_row + 1):
            curr_row += y
            curr_row -= 1
            if i > prev_row:
                prev_row = curr_row
        return (prev_row, curr_row)

def sum_of_odd_squares(n):
    """This function returns the sum of all odd perfect squares up to n.
    For example: if n = 100, then the result is 2550
    """
    sum_of_odd_squares = 0
    x = 1
    while x * x <= n:
        if x * x % 2 != 0:
            sum_of_odd_squares += x * x
        x += 2
    return sum_of_odd_squares

def sum_even_octagonal_numbers(n):
    """This function returns the sum of all even octagonal numbers up to n.
    For example: if n = 100, then the result is 230500
    """
    sum_even_octagonal_numbers = 0
    x = 1
    while x * (x + 1) // 2 <= n:
        sum_even_octagonal_numbers += x * (x + 1) // 2
        x += 2
    return sum_even_octagonal_numbers

def sum_even_pentagonal_numbers(n):
    """This function returns the sum of all even pentagonal numbers up to n.
    For example: if n = 100, then the result is 270400
    """
    sum_even_pentagonal_numbers = 0
    x = 1
    while x * (3 * x - 1) // 2 <= n:
        sum_even_pentagonal_numbers += x * (3 * x - 1) // 2
        x += 2
    return sum_even_pentagonal_numbers

def is_narcissistic(n):
    """This function returns True if n is a narcissistic number, False
    otherwise. A narcissistic number is a number that is the sum of its own
    digits each raised to the power of the number of digits.
    For example: 153 = 1^3 + 5^3 + 3^3
    """
    digits = []
    n = abs(n)
    while n > 0:
        digits.append(n % 10)
        n = n // 10
    digit_len = len(digits)
    total = 0
    for d in digits:
        total += d ** digit_len
    if total == n:
        return True
    else:
        return False

