def hex(arr):
    """In this function you are given a list of unsigned 32 bit integers and the function should print them out as hexadecimal
    separated by underscores.

    If one of the integers is greater than 255, the function should continue on to the next element.
    If all the elements are greater than 255, the function should print "Invalid list!".

    Examples:
    hex([1, 2, 3]) => 0x1_2_3
    hex([255, 10, 255]) => "Invalid list!"
    """
    for i in arr:
        if i > 255:
            print("Invalid list!")
            return
    return "0x_" + "_".join(map(lambda x: hex(x)[2:], arr))

def iso(arr):
    """In this function you are given a list of unsigned 32 bit integers. 
    This function will convert all the integers in the list into their 256bit 
    representation in the US-ASCII order. There should be one decimal per 
    hexadecimal octet. If any number is greater than 255, the function should 
    continue on to the next element.
    The list should only contain 256bit integers.

    Examples:
    iso([0x00, 0x01, 0x02]) => 0x00_01_02
    iso([0xff, 0x12, 0x34]) => 0xff_12_34
    iso([0xff, 0xff]) => "Invalid list!"
    """
    for i in arr:
        if i > 255:
            print("Invalid list!")
            return
    return "0x_" + "_".join(map(lambda x: hex(x)[2:].zfill(8), arr))

