def get_file_stats(stats, target_files):
    """Given a dictionary of file name to stats, return only those files with
    the given stats.
    """
    new_stats = {}
    for file, stats in stats.items():
        if stats == target_files:
            new_stats[file] = stats

    return new_stats


def latest_time(last_runs, file_name):
    """You are given a dictionary of file name to stats. Return the latest time for
    that file. The latest time is the time when the file was last executed.
    If no stats are given, return -1.
    """
    latest = 0
    for time, stats in last_runs.items():
        if stats["time"] > latest:
            latest = stats["time"]

    return latest


def histogram(file_stats, file_name):
    """Given a dictionary of file name to stats, return the amount of times the
    file was executed, up to a maximum of a given count.
    You may assume that the keys are unique.
    """
    hist = {}

    for file, stats in file_stats.items():
        if stats["name"] == file_name:
            hist[file] = stats["executions"]

    hist = sorted(hist.items(), key=lambda x: x[1], reverse=True)

    hist = list(map(lambda x: str(x[1]), hist))

    return str(hist[0]) if len(hist) != 0 else str(0)


