def is_isogram(string):
    """Given a string, return True if all characters in the string are unique, or False otherwise.
    Examples:
    is_isogram("Dermatoglyphics") => True
    is_isogram("aba") => False
    is_isogram("moOse") => False
    """
    if len(string) == 1:
        return True

    chars = set()

    for char in string:
        if char.lower() in chars:
            return False
        chars.add(char.lower())

    return True


