def intersection(l1, l2):
    """
    Given two list, return a list that contains only the common elements from both list.
    Do not use a built-in function intersection().

    Example 1:

        Input: [1, 2, 3, 4, 5, 6], [1, 3, 5, 7, 9]
        Output: [1, 3, 5]
    """
    if not l1 or not l2:
        return []

    out = []
    for e1 in l1:
        if e1 in l2:
            out.append(e1)
