def left_rotate(nums, d):
    """Perform a left rotation by 'd' number of steps in the array.
    """
    n = len(nums)
    if d < 0:
        return nums
    while d != 0:
        d -= 1
        a = nums[0]
        for i in range(n - 1):
            nums[i] = nums[i + 1]
        nums[n - 1] = a
    return nums

def right_rotate(nums, d):
    """Perform a right rotation by 'd' number of steps in the array.
    """
    n = len(nums)
    if d < 0:
        return nums
    while d != 0:
        d -= 1
        a = nums[n - 1]
        for i in range(n - 1):
            nums[i] = nums[i + 1]
        nums[0] = a
    return nums

