def matching_brackets(brace_seq):
    '''
    You are given a string of brackets, that consists of three types of brackets:
    brackets in parenthesis, brackets in curly braces, and brackets in square braces.
    Your task is to check if the string contains balanced brackets.
    The string contains brackets only in three types of brackets and the result
    of checking brackets should be true if the string contains balanced brackets.
    You can expect that:
    - for all valid brackets,
        the number of closing brackets is at most the number of opening brackets
        - for all valid brackets,
        the string cannot contain closing brackets that are not opening brackets
    If the string contains balanced brackets, the function returns true,
    otherwise, the function returns false.

    Examples:
    matching_brackets('(') ==> false
    matching_brackets('()') ==> true
    matching_brackets('()()') ==> true
    matching_brackets('(())') ==> true
    matching_brackets(')(') ==> false
    matching_brackets('()()(') ==> false
    matching_brackets('(()())') ==> true
    matching_brackets('(()))') ==> false
    matching_brackets('()(()(()')) ==> false
    '''
    pstack = []
    for char in brace_seq:
        if char in '()[]{}':
            if char in '[]':
                if char == '(' and not pstack:
                    pstack.append(char)
                elif char == '(' and pstack[-1] == '(':
                    pstack.pop()
                else:
                    pstack.append(char)
            elif char in '{}':
                if char == '(' and not pstack:
                    pstack.append(char)
                elif char == '(' and pstack[-1] == '{':
                    pstack.pop()
                elif char == '{' and pstack[-1] == '{':
                    pstack.pop()
                elif char == '{' and pstack[-1] == '}':
                    pstack.pop()
                else:
                    pstack.append(char)
            elif char in '[]':
                if char == ')' and not pstack:
                    pstack.append(char)
                elif char == ')' and pstack[-1] == '[':
                    pstack.pop()
                elif char == '[' and pstack[-1] == '[':
                    pstack.pop()
                elif char == '[' and pstack[-1] == ']':
                    pstack.pop()
                else:
                    pstack.append(char)
    if not pstack:
        return True
    else:
        return False


def balanced_parens(n):
    '''
    You are given an integer n.
    In one move, you can add exactly one character at the beginning of a string of
    length n with at most two distinct characters.
    Determine the minimum number of moves needed to obtain at least a string with
    at least two distinct characters.

    Examples:
    balanced_parens(2) ==> 1
    balanced_parens(3) ==> 2
    balanced_parens(6) ==> 5
    balanced_parens(8) ==> 6
    '''
    import itertools
    num1 = 0
    for i in itertools.combinations(range(n), 2):
        num1 += max(1, (i[0] == i[1] + 1 or (i[0] == i[1] - 1 and i[1] != 0)))
    return num1


