    'e'

    >>> first_not_repeating_char('aabbcc')
    None
    '''
    dict_ = {}
    for x in input_str:
        if x not in dict_:
            dict_[x] = 1
        else:
            dict_[x] += 1
    for k, v in dict_.items():
        if v == 1:
            return k
    return None


