def factorial(n):
    """Given a positive integer n, return the product of all integers in the range 1, n.
    For example:
    factorial(3)  == 6
    factorial(4)  == 24
    """
    if n < 1:
        return 0
    return 1 if n == 1 else n * factorial(n - 1)

