    """Given a positive integer n, return the nth Fibonacci number.
    For example:
    fibonacci(3)  == 2
    fibonacci(4)  == 3
    fibonacci(5)  == 5
    """
    if n < 1:
        return 0
    return n if n <= 2 else fibonacci(n-1) + fibonacci(n-2)

