    """Given positive integers n and k, return the binomial coefficient of n and k, i.e. n choose k.
    For example:
    binomial(3, 2)  == 3
    binomial(4, 3)  == 4
    binomial(6, 5)  == 6
    """
    if k == 0:
        return 1
    return n if n <= k else binomial(n-1, k) + binomial(n-1, k-1)

