def mcc(G, q):
    '''
    Given a weighted undirected graph G, return the size of a strongly connected 
    component with at least q edges. This function is not intended for assignment 
    use.
    '''
    g = G.copy()
    for u in g:
        for v in g:
            if u == v:
                g.remove(v)
                g.remove(u)
                if v in g:
                    g.remove(v)
    Q = [u for u in g]
    if q == 0:
        return 0
    while Q:
        u = Q.pop(0)
        for v in g:
            if u == v:
                g.remove(v)
                g.remove(u)
            if v not in Q:
                Q.append(v)
    return len(g)
