    # Base cases.
    if n == 0:
        return 0
    if n == 1:
        return 1

    # Recursive case.
    # n is the index of the current position in the sequence.
    # f(n) = f(n-1) + f(n-2)
    # f(n) = f(n-1) + f(n-2) + f(n-3)
    return nth_term(n-1) + nth_term(n-2) + nth_term(n-3)

